private func startSession() { isScanning = true; roomCaptureView?.captureSession.run(configuration: roomCaptureSessionConfig); setActiveNavBar() }
private func stopSession() { isScanning = false; roomCaptureView?.captureSession.stop(); setCompleteNavBar() }
@IBAction func doneScanning(_ sender: UIBarButtonItem) { if isScanning { stopSession() } else { cancelScanning(sender) } }
@IBAction func exportResults(_ sender: UIButton) { let destinationFolderURL = FileManager.default.temporaryDirectory.appending(path: "Export"); let destinationURL = destinationFolderURL.appending(path: "Room.usdz"); let capturedRoomURL = destinationFolderURL.appending(path: "Room.json"); try FileManager.default.createDirectory(at: destinationFolderURL, withIntermediateDirectories: true); let jsonData = try JSONEncoder().encode(finalResults); try jsonData.write(to: capturedRoomURL); try finalResults?.export(to: destinationURL, exportOptions: .parametric); let activityVC = UIActivityViewController(activityItems: [destinationFolderURL], applicationActivities: nil); activityVC.modalPresentationStyle = .popover; present(activityVC, animated: true) }
